   18	import (
   19		"bufio"
   20		"fmt"
   21		"io"
   22		"strings"
   23	)
   24	
   25	// File maps section -> key -> value.
   26	type File map[string]map[string]string
   27	
   28	// SyntaxError reports a malformed line.
   29	type SyntaxError struct {
   30		Line int
   31		Text string
   32	}
   33	
   34	func (e *SyntaxError) Error() string { return fmt.Sprintf("ini: line %d: syntax error: %q", e.Line, e.Text) }
   35	
   36	// Get returns the value of key in section.
   37	func (f File) Get(section, key string) (string, bool) {
   38		s, ok := f[strings.ToLower(section)]
