{"content":"package ini

import (
	"strings"
	"testing"
)

func TestDocumentedEdges(t *testing.T) {
	doc := "\n   \n# hash comment\n  ; indented comment\n[Fancy SEC]\nk1 = a=b=c\nk2 = x ; keep? no: a;b kept\nk2 = later\nk3 = \"  q  ;  inside  \"\nk4 = \"q\" ; trailing\nk5 = #ff0000\nk6 = a # comment\nk1 = final\n"
	f, err := Parse(strings.NewReader(doc))
	if err != nil {
		t.Fatal(err)
	}
	check := func(sec, key, want string, wantOK bool) {
		t.Helper()
		got, ok := f.Get(sec, key)
		if ok != wantOK || (!wantOK && ok) || (wantOK && got != want) {
			t.Errorf("%s.%s = %q,%v want %q,%v", sec, key, got, ok, want, wantOK)
		}
	}
	// sections lower-cased, trimmed
	check("fancy sec", "k1", "a=b=c", true)      // first '=' splits
	check("Fancy  SEC", "k2", "later", true)     // overwrite wins
	check("fancy sec", "k3", "  q  ;  inside  ", true) // quotes keep whitespace, no inline strip
	check("fancy sec", "k4", "q", true)          // quoted with trailing comment
	check("fancy sec", "k5", "#ff0000", true)    // '#' at value start is not a comment
	check("fancy sec", "k6", "a", true)          // ' #' starts inline comment
}

func TestA_b_Kept(t *testing.T) {
	f, err := Parse(strings.NewReader("x = a;b\n"))
	if err != nil {
		t.Fatal(err)
	}
	if got, ok := f.Get("", "x"); !ok || got != "a;b" {
		t.Errorf("x = %q,%v want \"a;b\"", got, ok)
	}
}
